// Railway Infrastructure as Code for the whole production environment.
// Generated by `railway config pull`, then corrected so the settings that the
// retired railway.json / railway.wake-broker.json enforced are kept. Every
// resource in the environment must stay declared here: a whole-project apply
// deletes what this file omits. Always `railway config plan` before `apply`.
import { bucket, defineRailway, github, postgres, preserve, project, service, volume } from "railway/iac";

export default defineRailway(() => {
  const leileiOs = github("nenecaramel/leilei-os", { checkSuites: false });

  const Postgres = postgres("Postgres", { region: "sfo" });
  Postgres.networking = { privateNetworkEndpoint: "postgres", tcpProxies: { "5432": {} } };
  const postgresVolume = volume("postgres-volume", { alerts: { usage: { "100": {}, "80": {}, "95": {} } }, allowOnlineResize: true, region: "sfo", sizeMB: 5000 });
  const leileiNativeLiveAttachments = bucket("leilei-native-live-attachments", { region: "sin" });

  const leileiWakeBroker = service("leilei-wake-broker", {
    source: leileiOs,
    build: { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "Dockerfile.wake-broker", watchPatterns: ["cmd/native-live-wake-broker/**", "Dockerfile.wake-broker"] },
    healthcheck: "/health",
    healthcheckTimeout: 30,
    replicas: { "sfo": 1 },
    // The Mac daemon long-polls the broker for wakes; it must never sleep.
    deploy: { restartPolicyType: "ALWAYS", sleepApplication: false },
    // build.dockerfilePath alone was ignored once Config as Code stopped
    // applying: the broker then built the server Dockerfile and failed its
    // healthcheck. The documented variable pins the path for the builder.
    env: { RAILWAY_DOCKERFILE_PATH: "Dockerfile.wake-broker", WAKE_BROKER_TOKEN: preserve() },
  });

  const leileiOsService = service("leilei-os", {
    source: leileiOs,
    // The Dockerfile build runs the production runtime gate; Railpack would skip it.
    build: { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "Dockerfile", watchPatterns: ["/src/**", "/drizzle/**", "/scripts/build-mcp-browser.mjs", "/tools/claude-bridge/**", "/package.json", "/pnpm-lock.yaml", "/pnpm-workspace.yaml", "/tsconfig.json", "/Dockerfile", "/.dockerignore", "/drizzle.config.ts"] },
    start: "node dist/app/index.js",
    healthcheck: "/ready",
    healthcheckTimeout: 30,
    preDeploy: "node dist/database/migrate.js",
    replicas: { "us-west2": 1 },
    deploy: { drainingSeconds: 15, overlapSeconds: 0, preDeployTimeoutSeconds: 600, sleepApplication: true },
    env: { AUTH0_ALLOWED_SUBJECT: preserve(), AUTH0_AUDIENCE: preserve(), AUTH0_CLIENT_ID: preserve(), AUTH0_ISSUER: preserve(), AUTH0_JWKS_URI: preserve(), AUTH0_REQUIRED_SCOPE: preserve(), DATABASE_URL: preserve(), ELEVENLABS_API_KEY: preserve(), LEILEIOS_REMOTE_SESSION_STORE_MAINTENANCE_MODE: preserve(), LEILEI_HEALTH_SYNC_KEY: preserve(), LEILEI_HEALTH_SYNC_USER_ID: preserve(), LEILEI_TOY_BRIDGE_KEY: preserve(), LEILEI_TOY_BRIDGE_USER_ID: preserve(), MCP_AUTH_TOKEN: preserve(), MCP_DEV_ALLOW_UNAUTHENTICATED: preserve(), MCP_INTERNAL_TOOL_PROFILES: preserve(), MCP_SERVER_URL: preserve(), MCP_SESSION_MAX_PER_USER: preserve(), MCP_USER_ID: preserve(), NATIVE_LIVE_ATTACHMENT_ACCESS_KEY_ID: preserve(), NATIVE_LIVE_ATTACHMENT_BUCKET: preserve(), NATIVE_LIVE_ATTACHMENT_ENDPOINT: preserve(), NATIVE_LIVE_ATTACHMENT_REGION: preserve(), NATIVE_LIVE_ATTACHMENT_SECRET_ACCESS_KEY: preserve(), NATIVE_LIVE_BREATH_SALIENCE_WEIGHT: preserve(), NATIVE_LIVE_CURIOSITY_DORMANT_AFTER_HOURS: preserve(), NATIVE_LIVE_DRIVE_ACTIVE_THRESHOLD: preserve(), NATIVE_LIVE_DRIVE_BASE_PRESSURE: preserve(), NATIVE_LIVE_DRIVE_DORMANT_AFTER_SATISFIED_HOURS: preserve(), NATIVE_LIVE_DRIVE_REINFORCEMENT_BOOST: preserve(), NATIVE_LIVE_MEMORY_DECAY_ARCHIVE_THRESHOLD: preserve(), NATIVE_LIVE_MEMORY_DECAY_FADING_THRESHOLD: preserve(), NATIVE_LIVE_MEMORY_DECAY_FEEL_HALF_LIFE_HOURS: preserve(), NATIVE_LIVE_MEMORY_DECAY_MEMORY_HALF_LIFE_HOURS: preserve(), NATIVE_LIVE_MIND_SEMANTIC_GROUPING_THRESHOLD: preserve(), NATIVE_LIVE_RELAY_AUTH_TOKEN: preserve(), NATIVE_LIVE_SEND_FILE_ENABLED: preserve(), NATIVE_LIVE_SILENCE_WAKE_ENABLED: preserve(), NATIVE_LIVE_THOUGHT_BASE_STRENGTH: preserve(), NATIVE_LIVE_THOUGHT_DORMANT_BELOW_STRENGTH: preserve(), NATIVE_LIVE_THOUGHT_HALF_LIFE_HOURS: preserve(), NATIVE_LIVE_THOUGHT_REINFORCEMENT_BOOST: preserve(), NATIVE_LIVE_TOPIC_DORMANT_AFTER_HOURS: preserve(), NATIVE_LIVE_WAKE_BROKER_AUTH_TOKEN: preserve(), NATIVE_LIVE_WAKE_BROKER_URL: preserve(), NODE_OPTIONS: preserve(), NOTION_PAT: preserve(), OAUTH_AS_ENABLED: preserve(), OAUTH_AS_UPSTREAM_CLIENT_ID: preserve(), OAUTH_AS_UPSTREAM_REDIRECT_URI: preserve(), OAUTH_CIMD_FETCH_TIMEOUT_MS: preserve(), OAUTH_CIMD_TRUSTED_CLIENT_IDS: preserve(), OAUTH_REFRESH_TOKEN_KEY: preserve(), OAUTH_STATIC_CLIENTS_JSON: preserve(), RAILWAY_DEPLOYMENT_DRAINING_SECONDS: preserve(), WEB_APP_ORIGIN: preserve(), WEB_AUTH0_AUDIENCE: preserve(), WEB_AUTH0_ISSUER: preserve(), WEB_AUTH0_JWKS_URI: preserve(), WEB_AUTH0_REQUIRED_SCOPE: preserve() },
  });

  return project("carefree-spontaneity", {
    resources: [leileiWakeBroker, leileiOsService, Postgres, postgresVolume, leileiNativeLiveAttachments],
  });
});
